const stock = new Map([
  ['sku-1', { onHand: 12, reserved: 2 }],
  ['sku-2', { onHand: 0, reserved: 0 }],
]);

function available(sku) {
  const s = stock.get(sku);
  return s ? s.onHand - s.reserved : 0;
}

function reserve(sku, qty) {
  if (available(sku) < qty) throw new Error('out of stock: ' + sku);
  stock.get(sku).reserved += qty;
}

module.exports = { stock, available, reserve };
